import json
import re

def extract_actions_from_iam_policy(policy_json_string: str) -> list:
    """
    Extracts all Actions from an AWS IAM policy JSON string.

    Args:
        policy_json_string: A JSON string representing an IAM policy

    Returns:
        A list of all Actions specified in the policy
    """
    try:
        policy = json.loads(policy_json_string)
    except json.JSONDecodeError:
        return []

    actions = []

    if isinstance(policy, dict):
        statements = policy.get('Statement', [])
        if not isinstance(statements, list):
            statements = [statements]

        for statement in statements:
            if isinstance(statement, dict):
                action_value = statement.get('Action')

                if action_value is not None:
                    if isinstance(action_value, str):
                        actions.append(action_value)
                    elif isinstance(action_value, list):
                        actions.extend(action_value)

    return actions
